using System.Globalization;using System.Text;using FitHub.Application.Administration;using FitHub.Domain.Equipment;using FitHub.Domain.Payments;using FitHub.Domain.Workouts;using FitHub.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;
namespace FitHub.Infrastructure.Administration;
public sealed class AdministratorDashboardService(FitHubDbContext db,TimeProvider timeProvider):IAdministratorDashboardService
{
    public async Task<AdministratorDashboardDto> GetAsync(CancellationToken ct=default)
    {
        var now=timeProvider.GetUtcNow();var start30=now.AddDays(-30);var start14=now.AddDays(-13).UtcDateTime.Date;
        var roleRows=await(from ur in db.UserRoles join role in db.Roles on ur.RoleId equals role.Id group ur by role.Name into g select new{Name=g.Key!,Count=g.Count()}).ToListAsync(ct);
        var memberUsers=await(from ur in db.UserRoles join role in db.Roles on ur.RoleId equals role.Id join user in db.Users on ur.UserId equals user.Id where role.Name=="Member" select new{user.Id,user.IsActive}).ToListAsync(ct);
        var memberIds=memberUsers.Select(x=>x.Id).ToArray();
        var latestMemberships=(await db.Memberships.AsNoTracking().Where(x=>memberIds.Contains(x.UserId)).OrderByDescending(x=>x.EndsAt).Select(x=>new{x.UserId,x.Status}).ToListAsync(ct)).GroupBy(x=>x.UserId).Select(g=>g.First()).ToList();var membershipRows=latestMemberships.GroupBy(x=>x.Status).ToDictionary(g=>g.Key.ToString(),g=>g.Count());membershipRows["NoMembership"]=Math.Max(0,memberUsers.Count-latestMemberships.Count);
        var confirmedPayments=db.Payments.AsNoTracking().Where(x=>!x.IsSeededDemo&&(x.Status==PaymentStatus.Succeeded||x.Status==PaymentStatus.Refunded));
        var revenue=await confirmedPayments.SumAsync(x=>(decimal?)(x.Amount-x.RefundedAmount),ct)??0m;
        var today=new DateTimeOffset(now.UtcDateTime.Date,TimeSpan.Zero);var monthStart=new DateTimeOffset(new DateTime(now.Year,now.Month,1),TimeSpan.Zero);
        var paymentsToday=await confirmedPayments.CountAsync(x=>x.PaidAt>=today,ct);var paymentsMonth=await confirmedPayments.CountAsync(x=>x.PaidAt>=monthStart,ct);
        var activeMemberships=await db.Memberships.AsNoTracking().CountAsync(x=>x.Status==FitHub.Domain.Memberships.MembershipStatus.Active&&x.StartsAt<=now&&x.EndsAt>now,ct);
        var activeMemberIds=memberUsers.Count(x=>x.IsActive);
        var pendingApprovals=await db.ClassSchedules.AsNoTracking().CountAsync(x=>x.Status==FitHub.Domain.Bookings.ClassScheduleStatus.PendingApproval,ct);
        var trainerCount=roleRows.FirstOrDefault(x=>x.Name=="Trainer")?.Count??0;
        var recentMembers=await(from ur in db.UserRoles join role in db.Roles on ur.RoleId equals role.Id join user in db.Users on ur.UserId equals user.Id where role.Name=="Member" orderby user.CreatedAt descending select new RecentMemberDto(user.Id,(user.PreferredName??(user.FirstName+" "+user.LastName)).Trim(),user.Email??string.Empty,user.CreatedAt)).Take(5).ToListAsync(ct);
        var attendance=await db.Attendances.AsNoTracking().Where(x=>x.CheckedInAt>=new DateTimeOffset(start14,TimeSpan.Zero)).Select(x=>x.CheckedInAt).ToListAsync(ct);var attendanceTrend=Enumerable.Range(0,14).Select(i=>new DateTimeOffset(start14.AddDays(i),TimeSpan.Zero)).Select(day=>new TrendPointDto(day,attendance.Count(x=>x.UtcDateTime.Date==day.UtcDateTime.Date))).ToList();
        var workouts=await db.WorkoutSessions.AsNoTracking().Where(x=>x.Status==WorkoutSessionStatus.Completed&&x.EndedAt>=start30).Select(x=>new{x.Id,x.UserId}).ToListAsync(ct);
        var operations=await EquipmentOperations(now.AddDays(-7),now,ct);var totalHours=(decimal)(now-now.AddDays(-7)).TotalHours*Math.Max(1,operations.Count);var utilization=totalHours==0?0:decimal.Round(operations.Sum(x=>x.UtilizationHours)*100m/totalHours,1);var downtime=decimal.Round(operations.Sum(x=>x.DowntimeHours),1);
        var openFaults=await db.FaultReports.AsNoTracking().CountAsync(x=>x.Status!=FaultReportStatus.Resolved&&x.Status!=FaultReportStatus.Rejected,ct);var parkingRows=await db.ParkingSpaces.AsNoTracking().Where(x=>x.IsActive).GroupBy(x=>x.CurrentState).Select(g=>new{State=g.Key,Count=g.Count()}).ToListAsync(ct);
        return new(roleRows.ToDictionary(x=>x.Name,x=>x.Count),membershipRows,revenue,"EUR",activeMemberIds,activeMemberships,paymentsToday,paymentsMonth,pendingApprovals,trainerCount,recentMembers,attendanceTrend,workouts.Count,workouts.Select(x=>x.UserId).Distinct().Count(),utilization,downtime,operations.Select(x=>new EquipmentOperationsDto(x.Name,totalHours==0?0:decimal.Round(x.UtilizationHours*100m/168m,1),decimal.Round(x.DowntimeHours,1))).ToList(),openFaults,parkingRows.ToDictionary(x=>x.State.ToString(),x=>x.Count));
    }
    public async Task<CsvReport> ExportAsync(string report,CancellationToken ct=default)
    {
        var csv=new StringBuilder();var name=report.ToLowerInvariant();
        switch(name){case"payments":csv.AppendLine("PaymentId,UserId,Plan,GrossAmount,RefundedAmount,NetAmount,Currency,PaidAt,CheckoutSessionId,PaymentIntentId");foreach(var x in await db.Payments.AsNoTracking().Include(x=>x.MembershipPlan).Where(x=>!x.IsSeededDemo&&(x.Status==PaymentStatus.Succeeded||x.Status==PaymentStatus.Refunded)).OrderByDescending(x=>x.PaidAt).ToListAsync(ct))Row(csv,x.Id,x.UserId,x.MembershipPlan.Name,x.Amount,x.RefundedAmount,x.Amount-x.RefundedAmount,x.Currency,x.PaidAt,x.ProviderReference,x.StripePaymentIntentId);break;case"attendance":csv.AppendLine("AttendanceId,UserId,CheckedInAt,CheckedOutAt");foreach(var x in await db.Attendances.AsNoTracking().OrderByDescending(x=>x.CheckedInAt).ToListAsync(ct))Row(csv,x.Id,x.UserId,x.CheckedInAt,x.CheckedOutAt);break;case"equipment":csv.AppendLine("Code,Name,State,Location,UpdatedAt");foreach(var x in await db.Equipment.AsNoTracking().OrderBy(x=>x.Code).ToListAsync(ct))Row(csv,x.Code,x.Name,x.CurrentState,x.Location,x.UpdatedAt);break;case"faults":csv.AppendLine("ReportId,Equipment,Category,Status,Serious,CreatedAt,ResolutionDate");foreach(var x in await db.FaultReports.AsNoTracking().Include(x=>x.Equipment).OrderByDescending(x=>x.CreatedAt).ToListAsync(ct))Row(csv,x.Id,x.Equipment.Name,x.Category,x.Status,x.IsSeriousSafetyConcern,x.CreatedAt,x.ResolutionDate);break;case"parking":csv.AppendLine("Code,Zone,State,Confidence,Source,EventTime");foreach(var x in await db.ParkingSpaces.AsNoTracking().OrderBy(x=>x.Code).ToListAsync(ct))Row(csv,x.Code,x.Zone,x.CurrentState,x.CurrentConfidence,x.CurrentSource,x.LastEventAt);break;default:throw new ArgumentException("Report must be payments, attendance, equipment, faults or parking.");}
        return new($"fithub-{name}-{timeProvider.GetUtcNow():yyyyMMdd}.csv",csv.ToString());
    }
    private async Task<List<OperationRow>> EquipmentOperations(DateTimeOffset start,DateTimeOffset end,CancellationToken ct){var items=await db.Equipment.AsNoTracking().Include(x=>x.StatusHistory).ToListAsync(ct);var results=new List<OperationRow>();foreach(var item in items){var ordered=item.StatusHistory.OrderBy(x=>x.OccurredAt).ToList();var before=ordered.LastOrDefault(x=>x.OccurredAt<=start);var firstAfter=ordered.FirstOrDefault(x=>x.OccurredAt>start);var state=before?.State??firstAfter?.PreviousState??item.CurrentState;var cursor=start;decimal utilized=0,down=0;foreach(var e in ordered.Where(x=>x.OccurredAt>start&&x.OccurredAt<=end)){Add(state,cursor,e.OccurredAt,ref utilized,ref down);state=e.State;cursor=e.OccurredAt;}Add(state,cursor,end,ref utilized,ref down);results.Add(new(item.Name,utilized,down));}return results;}
    private static void Add(EquipmentState state,DateTimeOffset from,DateTimeOffset to,ref decimal utilization,ref decimal downtime){var hours=(decimal)Math.Max(0,(to-from).TotalHours);if(state is EquipmentState.Occupied or EquipmentState.SharingAllowed)utilization+=hours;if(state is EquipmentState.Maintenance or EquipmentState.Offline)downtime+=hours;}
    private static void Row(StringBuilder csv,params object?[] values)=>csv.AppendLine(string.Join(',',values.Select(value=>Escape(value))));private static string Escape(object? value){var text=value switch{null=>"",IFormattable f=>f.ToString(null,CultureInfo.InvariantCulture),_=>value.ToString()??""};if(text.Length>0&&text[0] is '=' or '+' or '-' or '@')text="'"+text;return text.IndexOfAny([',','"','\n','\r'])>=0?$"\"{text.Replace("\"","\"\"")}\"":text;}
    private sealed record OperationRow(string Name,decimal UtilizationHours,decimal DowntimeHours);
}
